package com.jnapanam.sportszone.notification.dto;import com.jnapanam.sportszone.notification.model.*;import java.time.Instant;import java.util.UUID;public record NotificationResponse(UUID id,NotificationChannel channel,String category,String subject,String message,NotificationStatus status,int attempts,Instant readAt,Instant createdAt,Instant sentAt){public static NotificationResponse from(Notification n){return new NotificationResponse(n.getId(),n.getChannel(),n.getCategory(),n.getSubject(),n.getMessage(),n.getStatus(),n.getAttempts(),n.getReadAt(),n.getCreatedAt(),n.getSentAt());}}
